sources['io/tvos/HomeSearchInput.java']=Path('app/src/io/tvos/HomeSearchInput.java').read_text()
with tempfile.TemporaryDirectory(prefix='tvos-home-search-input-') as tmp:
 root=Path(tmp);write(root)
 for name,content in sources.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
 subprocess.run(['java','com.sun.tools.javac.Main','-d',tmp,*map(str,root.rglob('*.java'))],check=True)
 subprocess.run(['java','-cp',tmp,'io.tvos.SearchInputHarness'],check=True)
